def get_speech_therapy_priority(patient):
    """
    Compute the speech therapy priority of the patient.

    Parameters:
        patient (object): An object with attributes: income_level (high, medium, low), 
                          resource_availability (True/False), age, duration_of_condition (in months),
                          severity (1-10 scale), comorbidities (count), symptoms (list of strings)

    Returns:
        int: The computed priority score (0-12)
    """
    score = 0

    # Higher income level increases priority
    if patient.income_level == 'high':
        score += 2
    elif patient.income_level == 'medium':
        score += 1
    # else: low income, no addition

    # Higher resource availability is beneficial
    if patient.resource_availability:
        score += 2

    # Older patients may need more attention
    if patient.age > 65:
        score += 2
    elif 45 <= patient.age <= 64:
        score += 1

    # Longer duration of condition may indicate more complex needs
    if patient.duration_of_condition > 6:
        score += 3
    elif 3 <= patient.duration_of_condition <= 6:
        score += 2
    elif patient.duration_of_condition < 3:
        score += 1

    # Higher severity indicates more urgent care
    if patient.severity >= 7:
        score += 3
    elif 4 <= patient.severity <= 6:
        score += 2
    else:
        score += 1

    # More comorbidities may complicate treatment
    if patient.comorbidities >= 3:
        score += 2
    elif patient.comorbidities >= 1:
        score += 1

    # Specific symptoms that affect speech therapy needs
    if 'aphasia' in patient.symptoms or 'dysarthria' in patient.symptoms:
        score += 3
    elif 'difficulty_swallowing' in patient.symptoms or 'speech_delay' in patient.symptoms:
        score += 2
    else:
        score += 1

    return score

